import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

public class HashTablesTour {
    public static void main(String[] args) {
        String text = "the quick fox and the lazy dog and the cat";
        Map<String, Integer> counts = new HashMap<>();
        for (String word : text.split(" ")) counts.merge(word, 1, Integer::sum);   // O(1) average per word
        System.out.println("word counts (sorted for display): " + new TreeMap<>(counts));

        Set<String> seen = new HashSet<>();
        for (String word : text.split(" ")) {
            if (!seen.add(word)) {                     // add returns false if it was already there
                System.out.println("first repeated word: " + word);
                break;
            }
        }

        // Two-sum in one pass: remember each value's index, look up the complement
        int[] prices = {12, 7, 30, 18, 5, 21};
        int budget = 39;
        Map<Integer, Integer> indexOf = new HashMap<>();
        for (int i = 0; i < prices.length; i++) {
            Integer j = indexOf.get(budget - prices[i]);
            if (j != null) {
                System.out.println("items " + j + " and " + i + " cost " + prices[j] + " + " + prices[i] + " = " + budget);
                break;
            }
            indexOf.put(prices[i], i);
        }
    }
}

