public class HashFunctions {
    static int polynomialHash(String s) {
        int h = 0;
        for (int i = 0; i < s.length(); i++) h = 31 * h + s.charAt(i);   // wraps around in 32 bits
        return h;
    }

    static int additiveHash(String s) {
        int h = 0;
        for (int i = 0; i < s.length(); i++) h += s.charAt(i);
        return h;
    }

    static int bucket(int hash, int capacity) {
        return (hash & 0x7fffffff) % capacity;       // clear the sign bit first
    }

    static String histogram(String[] keys, boolean polynomial, int capacity) {
        int[] counts = new int[capacity];
        for (String k : keys) counts[bucket(polynomial ? polynomialHash(k) : additiveHash(k), capacity)]++;
        StringBuilder sb = new StringBuilder();
        for (int c : counts) sb.append(c).append(' ');
        return sb.toString().trim();
    }

    public static void main(String[] args) {
        for (String s : new String[]{"a", "cat", "hashing", "polynomial rolling"}) {
            System.out.println("hash(\"" + s + "\") = " + polynomialHash(s) + " (String.hashCode: " + s.hashCode()
                    + ") -> bucket " + bucket(polynomialHash(s), 8));
        }
        String[] keys = {"stop", "pots", "tops", "spot", "opts", "post", "cat", "act", "tac", "dog", "god", "odg"};
        System.out.println("12 keys, 13 buckets (count per bucket):");
        System.out.println("  additive:   " + histogram(keys, false, 13));
        System.out.println("  polynomial: " + histogram(keys, true, 13));
    }
}

