def polynomial_hash(s):
    """Java's String.hashCode: h = 31*h + c, wrapped to a signed 32-bit int."""
    h = 0
    for ch in s:
        h = (31 * h + ord(ch)) & 0xFFFFFFFF
    return h - (1 << 32) if h >= (1 << 31) else h


def additive_hash(s):
    return sum(ord(ch) for ch in s)


def bucket(h, capacity):
    return (h & 0x7FFFFFFF) % capacity  # clear the sign bit first


def histogram(keys, polynomial, capacity):
    counts = [0] * capacity
    for k in keys:
        counts[bucket(polynomial_hash(k) if polynomial else additive_hash(k), capacity)] += 1
    return " ".join(str(c) for c in counts)


for s in ["a", "cat", "hashing", "polynomial rolling"]:
    h = polynomial_hash(s)
    print(f'hash("{s}") = {h} (String.hashCode: {h}) -> bucket {bucket(h, 8)}')
