import java.util.ArrayList;
import java.util.List;

public class CollisionResolution {
    static final int CAPACITY = 7;

    public static void main(String[] args) {
        int[] keys = {10, 22, 31, 4, 15, 28, 17, 88, 59};

        // Separate chaining: a list per bucket
        List<List<Integer>> chains = new ArrayList<>();
        for (int i = 0; i < CAPACITY; i++) chains.add(new ArrayList<>());
        for (int k : keys) chains.get(k % CAPACITY).add(k);
        System.out.println("separate chaining (index = key % 7):");
        for (int i = 0; i < CAPACITY; i++) System.out.println("  " + i + ": " + chains.get(i));

        // Linear probing: one key per slot, step to the next slot on a collision
        Integer[] slots = new Integer[11];
        System.out.println("linear probing, 11 slots (index = key % 11):");
        for (int k : keys) {
            int i = k % slots.length, probes = 1;
            while (slots[i] != null) {
                i = (i + 1) % slots.length;   // wrap around
                probes++;
            }
            slots[i] = k;
            System.out.println("  insert " + k + ": home " + (k % slots.length) + ", stored at " + i + " after " + probes + " probe(s)");
        }
        StringBuilder table = new StringBuilder();
        for (Integer s : slots) table.append(s == null ? "_" : s.toString()).append(' ');
        System.out.println("  table: " + table.toString().trim());

        for (int k : new int[]{88, 50}) {
            int i = k % slots.length, probes = 1;
            while (slots[i] != null && slots[i] != k) {   // stop at the key or at an empty slot
                i = (i + 1) % slots.length;
                probes++;
            }
            System.out.println("  lookup " + k + ": " + (slots[i] == null ? "absent" : "found") + " after " + probes + " probe(s)");
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class HashMapOperations {
    public static void main(String[] args) {
        Map<String, Integer> grades = new HashMap<>();
        System.out.println("put(ana, 88) returned " + grades.put("ana", 88));
        grades.put("ben", 72);
        grades.put("cleo", 95);
        System.out.println("put(ben, 79) returned " + grades.put("ben", 79) + " (old value replaced)");
        System.out.println("get(cleo) = " + grades.get("cleo") + ", get(dan) = " + grades.get("dan"));
        System.out.println("getOrDefault(dan, 0) = " + grades.getOrDefault("dan", 0));
        System.out.println("containsKey(ana) = " + grades.containsKey("ana"));
        System.out.println("remove(ana) returned " + grades.remove("ana") + ", size now " + grades.size());

        Map<Character, Integer> letters = new TreeMap<>();      // sorted keys for display
        for (char c : "mississippi".toCharArray()) letters.merge(c, 1, Integer::sum);
        System.out.println("letters in mississippi: " + letters);

        Map<String, List<String>> groups = new HashMap<>();
        for (String w : new String[]{"listen", "google", "silent", "enlist", "banana", "gogole"}) {
            char[] chars = w.toCharArray();
            Arrays.sort(chars);
            groups.computeIfAbsent(new String(chars), k -> new ArrayList<>()).add(w);
        }
        for (String key : new TreeMap<>(groups).keySet()) {
            System.out.println("  " + key + " -> " + groups.get(key));
        }
    }
}

