import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class HashSets {
    static class BadPoint {                        // equals without hashCode: breaks the contract
        final int x, y;
        BadPoint(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            return o instanceof BadPoint p && p.x == x && p.y == y;
        }
    }

    record GoodPoint(int x, int y) {}              // records generate equals AND hashCode

    public static void main(String[] args) {
        List<String> visitors = List.of("ana", "ben", "ana", "cleo", "ben", "ana", "dev");
        Set<String> unique = new HashSet<>();
        List<String> repeats = new ArrayList<>();
        for (String v : visitors) if (!unique.add(v)) repeats.add(v);   // add returns false for repeats
        System.out.println("unique visitors: " + new TreeSet<>(unique) + ", repeat visits: " + repeats);
        System.out.println("contains(cleo) = " + unique.contains("cleo") + ", contains(zoe) = " + unique.contains("zoe"));

        Set<String> monday = new HashSet<>(List.of("ana", "ben", "cleo"));
        Set<String> tuesday = new HashSet<>(List.of("ben", "dev", "cleo", "eli"));
        Set<String> both = new HashSet<>(monday);
        both.retainAll(tuesday);
        Set<String> either = new HashSet<>(monday);
        either.addAll(tuesday);
        Set<String> onlyMonday = new HashSet<>(monday);
        onlyMonday.removeAll(tuesday);
        System.out.println("both days: " + new TreeSet<>(both) + ", either day: " + new TreeSet<>(either)
                + ", only monday: " + new TreeSet<>(onlyMonday));

        Set<BadPoint> bad = new HashSet<>();
        bad.add(new BadPoint(1, 2));
        bad.add(new BadPoint(1, 2));
        System.out.println("broken contract: size " + bad.size() + ", contains (1,2)? " + bad.contains(new BadPoint(1, 2)));
        Set<GoodPoint> good = new HashSet<>();
        good.add(new GoodPoint(1, 2));
        good.add(new GoodPoint(1, 2));
        System.out.println("equals + hashCode: size " + good.size() + ", contains (1,2)? " + good.contains(new GoodPoint(1, 2)));
    }
}

