import java.util.ArrayList;
import java.util.List;

public class LoadFactor {
    static int spread(int key) {
        return (int) (key * 2654435761L) & 0x7fffffff;   // multiplicative hash, low 32 bits
    }

    static class ChainedTable {
        List<List<Integer>> buckets = newBuckets(4);
        int size = 0;

        static List<List<Integer>> newBuckets(int n) {
            List<List<Integer>> b = new ArrayList<>();
            for (int i = 0; i < n; i++) b.add(new ArrayList<>());
            return b;
        }

        void add(int key) {
            if ((size + 1) > 0.75 * buckets.size()) rehash();
            buckets.get(spread(key) % buckets.size()).add(key);
            size++;
        }

        void rehash() {
            List<List<Integer>> old = buckets;
            buckets = newBuckets(old.size() * 2);
            for (List<Integer> chain : old) for (int k : chain) buckets.get(spread(k) % buckets.size()).add(k);
            System.out.println("  rehash at size " + size + ": " + old.size() + " -> " + buckets.size() + " buckets");
        }

        int longestChain() {
            int best = 0;
            for (List<Integer> chain : buckets) best = Math.max(best, chain.size());
            return best;
        }
    }

    public static void main(String[] args) {
        ChainedTable table = new ChainedTable();
        for (int key = 1; key <= 20; key++) table.add(key * 7);
        System.out.printf("20 keys in %d buckets: load factor %.3f, longest chain %d%n",
                table.buckets.size(), table.size / (double) table.buckets.size(), table.longestChain());

        int capacity = 101;
        Integer[] slots = new Integer[capacity];
        int inserted = 0;
        long probes = 0;
        System.out.println("linear probing, 101 slots:");
        for (double target : new double[]{0.25, 0.5, 0.75, 0.9}) {
            long probesBefore = probes;
            int insertedBefore = inserted;
            while (inserted < target * capacity) {
                int key = 1000 + inserted * 13;
                int i = spread(key) % capacity;
                probes++;
                while (slots[i] != null) { i = (i + 1) % capacity; probes++; }
                slots[i] = key;
                inserted++;
            }
            System.out.printf("  load %.2f: average probes for the last %d inserts = %.2f%n",
                    inserted / (double) capacity, inserted - insertedBefore,
                    (probes - probesBefore) / (double) (inserted - insertedBefore));
        }
    }
}

