def spread(key):
    return ((key * 2654435761) & 0xFFFFFFFF) & 0x7FFFFFFF  # multiplicative hash


class ChainedTable:
    def __init__(self):
        self.buckets = [[] for _ in range(4)]
        self.size = 0

    def add(self, key):
        if self.size + 1 > 0.75 * len(self.buckets):
            self.rehash()
        self.buckets[spread(key) % len(self.buckets)].append(key)
        self.size += 1

    def rehash(self):
        old = self.buckets
        self.buckets = [[] for _ in range(len(old) * 2)]
        for chain in old:
            for k in chain:
                self.buckets[spread(k) % len(self.buckets)].append(k)
        print(f"  rehash at size {self.size}: {len(old)} -> {len(self.buckets)} buckets")

    def longest_chain(self):
        return max(len(chain) for chain in self.buckets)


